    29|import { authorizeInternalDeploymentRequest, InternalDeployAuthError } from '../services/ivx-internal-deploy-auth';
    30|
    31|type WorkerEnqueueRequest = {
    32|  goal?: unknown;
    33|  templateMode?: unknown;
    34|  proposedPlan?: unknown;
    35|  filesAffected?: unknown;
    36|  riskLevel?: unknown;
    37|  rollbackOption?: unknown;
    38|  approvePatch?: unknown;
    39|  approveGitDeploy?: unknown;
    40|  validationMode?: unknown;
    41|};
    42|
    43|const TEMPLATE_MODES = [
    44|  'NEW_APP_FROM_SCRATCH',
    45|  'NEW_MODULE_FROM_SCRATCH',
    46|  'NEW_FEATURE',
    47|  'BUG_FIX',
    48|  'REFACTOR',
    49|  'BUSINESS_WORKFLOW',
    50|  'INVESTOR_WORKFLOW',
    51|  'CRM_WORKFLOW',
    52|] as const;
    53|
    54|type WorkerTemplateMode = (typeof TEMPLATE_MODES)[number];
    55|
    56|function normalizeTemplateMode(value: unknown): WorkerTemplateMode {
    57|  const raw = readTrimmed(value).toUpperCase();
    58|  return (TEMPLATE_MODES as readonly string[]).includes(raw) ? (raw as WorkerTemplateMode) : 'NEW_FEATURE';
    59|}
    60|
    61|function readTrimmed(value: unknown): string {
    62|  return typeof value === 'string' ? value.trim() : '';
    63|}
    64|
    65|function readBoolean(value: unknown): boolean {
    66|  return value === true || readTrimmed(value).toLowerCase() === 'true';
    67|}
    68|
    69|function readStringArray(value: unknown): string[] {
    70|  if (!Array.isArray(value)) return [];
    71|  return Array.from(new Set(value.map((item) => readTrimmed(item)).filter(Boolean))).slice(0, 25);
    72|}
    73|
    74|function normalizeRiskLevel(value: unknown): 'low' | 'medium' | 'high' {
    75|  const risk = readTrimmed(value).toLowerCase();
    76|  return risk === 'low' || risk === 'high' ? risk : 'medium';
    77|}
    78|
    79|function normalizeValidationMode(value: unknown): 'focused' | 'typecheck' {
    80|  return readTrimmed(value).toLowerCase() === 'typecheck' ? 'typecheck' : 'focused';
    81|}
    82|
    83|function statusForError(error: unknown): number {
    84|  const message = error instanceof Error ? error.message.toLowerCase() : '';
    85|  // Auth guard failures must return 401/403, never 500.
    86|  if (message.includes('missing bearer token') || message.includes('invalid or expired')) return 401;
    87|  if (message.includes('privileged ivx access is required') || message.includes('owner') || message.includes('auth guard failed') || message.includes('auth config failed') || message.includes('role guard failed')) return 403;
    88|  return 500;
    89|}
    90|
    91|function errorResponse(error: unknown): Response {
    92|  const message = error instanceof Error ? error.message : 'IVX senior developer worker failed.';
    93|  if (error instanceof InternalDeployAuthError) {
